#!/usr/bin/env bash\nset -euo pipefail\n\n# Create a temporary directory to simulate a .ssh folder\nTMPDIR=$(mktemp -d)\nSSH_DIR="$TMPDIR/.ssh"\nmkdir -p "$SSH_DIR"\n\n# Create dummy existing key pair and authorized_keys\ncat <<'EOF' > "$SSH_DIR/id_ed25519"\nold private key\nEOF\n\ncat <<'EOF' > "$SSH_DIR/id_ed25519.pub"\nold public key\nEOF\n\ncat <<'EOF' > "$SSH_DIR/authorized_keys"\noldkey\nEOF\n\n# Run the rotator script\n../src/rotate_ssh_keys.sh "$SSH_DIR"\n\n# Verify new private key exists\nif [[ ! -f "$SSH_DIR/id_ed25519" ]]; then\n  echo "New private key missing"\n  exit 1\nfi\n\n# Verify new public key exists\nif [[ ! -f "$SSH_DIR/id_ed25519.pub" ]]; then\n  echo "New public key missing"\n  exit 1\nfi\n\n# Verify backup files were created (pattern match)\nbackup_found=$(ls "$SSH_DIR"/id_ed25519.bak.* 2>/dev/null || true)\nif [[ -z "$backup_found" ]]; then\n  echo "Backup of old private key not found"\n  exit 1\nfi\n\n# Verify authorized_keys contains the dummy public key marker\nif ! grep -q "dummy-key-" "$SSH_DIR/authorized_keys"; then\n  echo "authorized_keys was not updated with new key"\n  exit 1\nfi\n\necho "All tests passed."
